#!/bin/sh
# Generated by forge. PreToolUse(Bash) tripwire: matches guard.rules patterns
# (POSIX ERE) against the JSON-escaped command. First deny wins, else first ask.
# A rule with a check (column 5) is a candidate only: its pattern pre-filters, and
# the named guard_check_* function below decides on the parsed command.
# The sandbox and permissions are the protection boundary; this is a tripwire.
# An ask nobody can answer (an autonomous run) goes to review.sh instead.
dir=$(dirname "$0")
input=$(cat)

# guard_check_ephemeral_exec: succeeds, printing why, when the command runs a package
# launcher (npx, bunx, bun x, npm exec, pnpm dlx, pnpx, yarn dlx, uvx, uv tool run,
# pipx run, deno run npm:/jsr:/URL, and the create / init forms that run an
# initializer package) on something it would fetch from a registry: always for
# pnpm/yarn dlx and create, and pipx run; for the others, a package option
# (--package, --from, --with, ...), a version or URL spec, or a command not installed
# where it runs (node_modules/.bin or .venv/bin, from that directory up to the
# repository root). Only options before the command name belong to the launcher (npx
# tsc -p tsconfig.json is tsc's -p); a package manager's options before its
# subcommand (npm --yes exec) and a wrapper's options with their arguments (nice -n
# 5, sudo -u bob, timeout -s KILL 5) are skipped. Compound commands are split on ;,
# &&, ||, |, &, newlines and subshells; cd is followed; heredoc bodies and quoted
# text are not commands; sh -c '...', eval, env -S and find -exec are parsed; a
# command name expanded at run time ($N) is flagged, since it cannot be followed.
guard_check_ephemeral_exec() {
  _ge_found=$(printf '%s' "$input" | awk -v home="${HOME:-}" '
    function jstr(buf, key,   s, n, i, c, d, out, h, v, k) {
      if (!match(buf, "\"" key "\"[[:space:]]*:[[:space:]]*\"")) return ""
      s = substr(buf, RSTART + RLENGTH); n = length(s); out = ""
      for (i = 1; i <= n; i++) {
        c = substr(s, i, 1)
        if (c == "\"") break
        if (c != "\\") { out = out c; continue }
        i++; d = substr(s, i, 1)
        if (d == "n") out = out "\n"
        else if (d == "t") out = out "\t"
        else if (d == "r") out = out ""
        else if (d == "u") {
          h = tolower(substr(s, i + 1, 4)); v = 0
          for (k = 1; k <= 4; k++) v = v * 16 + index("0123456789abcdef", substr(h, k, 1)) - 1
          out = out ((v > 0 && v < 128) ? sprintf("%c", v) : "?"); i += 4
        } else out = out d
      }
      return out
    }
    function norm(p,   n, a, i, m, st, out) {
      n = split(p, a, "/"); m = 0
      for (i = 1; i <= n; i++) {
        if (a[i] == "" || a[i] == ".") continue
        if (a[i] == "..") { if (m) m--; continue }
        st[++m] = a[i]
      }
      out = ""
      for (i = 1; i <= m; i++) out = out "/" st[i]
      return out == "" ? "/" : out
    }
    function chdir(t) { return chdirb(D, t) }
    function chdirb(base, t) {
      if (base == "?") return "?"
      if (t == "" || t == "~") return home == "" ? "?" : home
      if (t == "-" || t ~ /[$`*?]/) return "?"
      if (t ~ /^~\//) { if (home == "") return "?"; t = home substr(t, 2) }
      if (t !~ /^\//) t = base "/" t
      return norm(t)
    }
    function endword() {
      if (inw) { if (skipnext) skipnext = 0; else W[++nw] = w }
      w = ""; inw = 0
    }
    function endseg() { endword(); if (nw) seg(); nw = 0; skipnext = 0 }
    # parse <s>: splits a command line into simple commands, each handled by seg()
    function parse(s,   n, i, c, nx, hds, k, ent, st, dl, rest, line, q) {
      n = length(s); q = ""; hds = ""
      for (i = 1; i <= n; i++) {
        c = substr(s, i, 1); nx = substr(s, i + 1, 1)
        if (q == "\047") { if (c == "\047") q = ""; else w = w c; continue }
        if (q == "\"") {
          if (c == "\\" && nx ~ /[$`"\\]/) { w = w nx; i++; continue }
          if (c == "\"") q = ""; else w = w c
          continue
        }
        if (c == "\\") { if (nx != "\n") { w = w nx; inw = 1 }; i++; continue }
        if (c == "\047" || c == "\"") { q = c; inw = 1; continue }
        if (c == " " || c == "\t") { endword(); continue }
        if (c == "#" && !inw) { k = index(substr(s, i), "\n"); if (!k) break; i += k - 2; continue }
        if (c == "\n") {
          endseg()
          while (hds != "") {
            k = index(hds, "\n"); ent = substr(hds, 1, k - 1); hds = substr(hds, k + 1)
            st = substr(ent, 1, 1); dl = substr(ent, 2)
            while (i < n) {
              rest = substr(s, i + 1); k = index(rest, "\n")
              line = k ? substr(rest, 1, k - 1) : rest
              i += k ? k : length(rest)
              if (st == "1") sub(/^\t+/, "", line)
              if (line == dl) break
            }
          }
          continue
        }
        if (c == "&" && nx == ">") { endword(); i++; if (substr(s, i + 1, 1) == ">") i++; skipnext = 1; continue }
        if (c ~ /[;&|()`]/) { endseg(); if ((c == "&" || c == "|") && nx == c) i++; continue }
        if (c == "$" && nx == "(") { endseg(); i++; continue }
        if (c == "<" || c == ">") {
          if (inw && w ~ /^[0-9]+$/) { w = ""; inw = 0 } else endword()
          if (c == "<" && nx == "(") { endseg(); i++; continue }
          if (c == "<" && nx == "<") {
            if (substr(s, i + 2, 1) == "<") { i += 2; skipnext = 1; continue }
            i += 2; st = 0
            if (substr(s, i, 1) == "-") { st = 1; i++ }
            while (substr(s, i, 1) ~ /[ \t]/) i++
            dl = ""
            for (; i <= n; i++) {
              c = substr(s, i, 1)
              if (c ~ /[ \t\n;&|<>()]/) break
              if (c != "\047" && c != "\"" && c != "\\") dl = dl c
            }
            i--
            if (dl != "") hds = hds st dl "\n"
            continue
          }
          if (nx == ">" || nx == "|") { i++; nx = substr(s, i + 1, 1) }
          if (nx == "&") { i++; while (substr(s, i + 1, 1) ~ /[0-9-]/) i++; continue }
          skipnext = 1
          continue
        }
        w = w c; inw = 1
      }
      endseg()
    }
    # words <from> <to>: W[from..to] joined with spaces (what eval runs)
    function words(a, b,   out) {
      out = ""
      for (; a <= b; a++) out = out (out == "" ? "" : " ") W[a]
      return out
    }
    # wrapopt <wrapper> <option>: 1 when the wrapper option takes the next word as
    # its argument, 2 when that argument is a directory the command then runs in
    function wrapopt(b, o) {
      if (b == "sudo") return o ~ /^(-D|--chdir)$/ ? 2 : o ~ /^(-[ugpCrtUhRT]|--(user|group|prompt|close-from|role|type|other-user|host|command-timeout))$/
      if (b == "doas") return o ~ /^-[uC]$/
      if (b == "env") return o ~ /^(-C|--chdir)$/ ? 2 : o ~ /^(-u|--unset|-P)$/
      if (b == "nice") return o ~ /^(-n|--adjustment)$/
      if (b == "ionice") return o ~ /^-[cnp]$/
      if (b == "timeout") return o ~ /^(-s|--signal|-k|--kill-after)$/
      if (b == "time") return o ~ /^(-f|--format|-o|--output)$/
      if (b == "exec") return o == "-a"
      if (b == "xargs") return o ~ /^(-[IiLnPsdEeaJR]|--(arg-file|max-args|max-procs|max-chars|delimiter|eof|replace|max-lines))$/
      if (b == "stdbuf") return o ~ /^-[ioe]$/
      return 0
    }
    # pmopt <manager> <option>: as wrapopt, for a package manager option before its subcommand
    function pmopt(b, o) {
      if (b == "npm") return o == "--prefix" ? 2 : o ~ /^(-w|--workspace|--registry|--cache|--userconfig|--globalconfig|--loglevel)$/
      if (b == "pnpm") return o ~ /^(-C|--dir)$/ ? 2 : o ~ /^(-F|--filter|--reporter|--loglevel|--workspace-concurrency)$/
      if (b == "yarn") return o == "--cwd" ? 2 : 0
      if (b == "bun") return o == "--cwd" ? 2 : o ~ /^(-c|--config|--env-file|-r|--preload)$/
      return 0
    }
    # seg: one simple command, in W[1..nw]; LD is the directory it runs in
    function seg(   k, x, b, j, o, t, sub_s, saved) {
      k = 1; LD = D
      while (k <= nw) {
        x = W[k]
        if (x ~ /^[A-Za-z_][A-Za-z0-9_]*=/) { k++; continue }
        b = x; sub(/.*\//, "", b)
        if (b !~ /^(sudo|doas|env|time|nohup|nice|ionice|exec|command|builtin|xargs|stdbuf|timeout)$/) break
        for (k++; k <= nw && W[k] ~ /^-./; k++) {
          o = W[k]
          if (o == "--") { k++; break }
          # env -S "<command>" splits its argument into a command
          if (b == "env" && (o == "-S" || o == "--split-string")) { sub_s = words(k + 1, nw); nw = 0; parse(sub_s); return }
          if (b == "env" && o ~ /^(-S.|--split-string=)/) { sub(/^(-S|--split-string=)/, "", o); sub_s = o " " words(k + 1, nw); nw = 0; parse(sub_s); return }
          t = wrapopt(b, o)
          if (t == 2) LD = chdirb(LD, W[k + 1])
          else if ((b == "sudo" && o ~ /^(-D.|--chdir=)/) || (b == "env" && o ~ /^(-C.|--chdir=)/)) { sub(/^(-D|-C|--chdir=)/, "", o); LD = chdirb(LD, o) }
          if (t) k++
        }
        if (b == "timeout") k++
      }
      if (k > nw) return
      b = W[k]
      # a command name expanded when the command runs (N=npx; $N cowsay) cannot be followed
      if (b ~ /[$`]/) { print "remote\tthe command name " b " is expanded when the command runs, so Forge cannot check what it runs"; return }
      sub(/.*\//, "", b)
      if (b == "cd" || b == "pushd") { D = chdir(k < nw ? W[k + 1] : ""); return }
      if (b == "eval") { sub_s = words(k + 1, nw); nw = 0; parse(sub_s); return }
      if (b ~ /^(sh|bash|zsh|dash|ksh)$/) {
        for (j = k + 1; j < nw; j++)
          if (W[j] ~ /^-[a-z]*c[a-z]*$/) { sub_s = W[j + 1]; saved = D; nw = 0; parse(sub_s); D = saved; return }
        return
      }
      if (b == "find") {
        # each -exec / -execdir / -ok / -okdir runs a command, up to ; or +
        sub_s = ""
        for (j = k + 1; j <= nw; j++) {
          if (W[j] !~ /^-(exec|execdir|ok|okdir)$/) continue
          for (o = j + 1; o <= nw && W[o] != ";" && W[o] != "+"; o++) ;
          sub_s = sub_s words(j + 1, o - 1) "\n"; j = o
        }
        saved = D; nw = 0; parse(sub_s); D = saved
        return
      }
      if (b == "npx" || b == "bunx") { launcher(k + 1, b, "node"); return }
      if (b == "pnpx") { launcher(k + 1, b, "dlx"); return }
      if (b == "uvx") { launcher(k + 1, b, "uv"); return }
      if (b == "uv" && W[k + 1] == "tool" && W[k + 2] == "run") { launcher(k + 3, "uv tool run", "uv"); return }
      if (b == "pipx" && W[k + 1] == "run") { launcher(k + 2, "pipx run", "dlx"); return }
      if (b == "deno") { deno(k + 1); return }
      if (b !~ /^(npm|pnpm|yarn|bun)$/) return
      # options of the package manager itself come before its subcommand (npm --yes exec, bun --bun x)
      for (j = k + 1; j <= nw && W[j] ~ /^-./; j++) {
        t = pmopt(b, W[j])
        if (t == 2) LD = chdirb(LD, W[j + 1])
        else if (W[j] ~ /^--(prefix|dir|cwd)=/) { o = W[j]; sub(/^[^=]*=/, "", o); LD = chdirb(LD, o) }
        if (t) j++
      }
      x = W[j]
      if (b == "npm" && (x == "exec" || x == "x")) launcher(j + 1, "npm exec", "npm")
      else if (b == "bun" && x == "x") launcher(j + 1, "bun x", "node")
      else if ((b == "pnpm" || b == "yarn") && x == "dlx") launcher(j + 1, b " dlx", "dlx")
      # create / init forms run the initializer package create-<name>: npm and bun
      # through their exec launcher (installed copy first), pnpm and yarn through dlx
      else if (x == "create" || (b == "npm" && (x == "init" || x == "innit"))) initializer(j + 1, b " " x, b)
    }
    # initializer <j> <name> <manager>: <manager> create|init <initializer> (npm init
    # without one only writes package.json)
    function initializer(j, name, pm,   o, x, v) {
      for (; j <= nw; j++) {
        o = W[j]
        if (o == "--") { j++; break }
        if (o !~ /^-./) break
        if (o ~ /^(-w|--workspace|--scope|--init-module)$/) j++
      }
      if (j > nw) return
      x = W[j]
      if (pm == "bun" && x ~ /^[.\/~]/) return
      if (pm == "bun" && x ~ /^[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+$/) { print "remote\t" name " " x " fetches the template from GitHub and runs it"; return }
      v = ""
      if (match(x, /.@/)) { v = substr(x, RSTART + 1); x = substr(x, 1, RSTART) }
      if (x ~ /^@[^\/]+$/) x = x "/create"
      else if (x ~ /^@[^\/]+\//) { o = x; sub(/\/.*/, "", o); sub(/^@[^\/]+\//, "", x); x = o "/create-" x }
      else x = "create-" x
      if (pm == "pnpm" || pm == "yarn") { print "remote\t" name " fetches " x " from a registry and runs it"; return }
      classify(x v, name, "node")
    }
    # deno <j>: deno run|x|serve with an npm:, jsr: or URL module fetches it
    function deno(j,   o) {
      if (W[j] != "run" && W[j] != "x" && W[j] != "serve") return
      for (j++; j <= nw; j++) {
        o = W[j]
        if (o == "--") { j++; break }
        if (o !~ /^-./) break
        if (o ~ /^(-c|--config|--import-map|--lock|--cert|--location|--seed|--ext|--env-file|--inspect|--watch)$/ && W[j + 1] !~ /^-/) j++
      }
      if (j <= nw && W[j] ~ /^(npm:|jsr:|https?:)/) print "remote\tdeno " W[j] " fetches the module from a registry and runs it"
    }
    # launcher: the options before the command name belong to the launcher (npm exec
    # also parses its own options after the name, up to --, unless -- comes first)
    function launcher(j, name, kind,   o, pkg, dd, cmd) {
      pkg = ""; dd = 0
      for (; j <= nw; j++) {
        o = W[j]
        if (o == "--") { dd = 1; j++; break }
        if (o !~ /^-/ || o == "-") break
        if (kind == "uv") {
          if (o ~ /^(--from|--with|--with-editable|--with-requirements|-w|--index|--index-url|--default-index|--extra-index-url|-i|-f|--find-links)$/) { pkg = o; j++ }
          else if (o ~ /^(--from|--with|--with-editable|--with-requirements|--index|--index-url|--default-index|--extra-index-url|--find-links)=/) pkg = o
          else if (o ~ /^(-p|--python|-C|--config-setting|--directory|--project|--cache-dir|--config-file|--color|--resolution|--prerelease|--exclude-newer|--index-strategy|--keyring-provider|--link-mode|--constraints|-c|--overrides|--build-constraints|--env-file|--python-preference)$/) j++
        } else {
          if (o ~ /^(-p|--package|-c|--call)$/) { pkg = o; j++ }
          else if (o ~ /^(--package|--call)=/) pkg = o
          else if (o ~ /^(-w|--workspace|--prefix|--registry|--cache|--userconfig|--allow-scripts|--loglevel)$/) j++
        }
      }
      cmd = j <= nw ? W[j] : ""
      if (kind == "npm" && !dd)
        for (o = j + 1; o <= nw && W[o] != "--"; o++) if (W[o] ~ /^(-p|--package|-c|--call)(=|$)/) pkg = W[o]
      if (kind == "dlx") { print "remote\t" name " fetches " (cmd == "" ? "a package" : cmd) " from a registry and runs it"; return }
      if (pkg != "") { sub(/=.*/, "", pkg); print "remote\t" name " " pkg " fetches a package from a registry and runs it"; return }
      if (cmd == "") return
      classify(cmd, name, kind)
    }
    # classify <spec> <launcher> <kind>: a bare name is looked up where the command
    # runs (LD); a version, URL or repository spec is fetched
    function classify(cmd, name, kind) {
      if (kind == "uv") {
        if (cmd ~ /^[A-Za-z0-9._-]+$/) print "py\t" LD "\t" cmd "\t" name
        else print "remote\t" name " " cmd " names a version or source that is fetched from a registry"
        return
      }
      if (cmd ~ /^[.\/~]/) return
      if (cmd ~ /^@[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+$/ || cmd ~ /^[A-Za-z0-9._-]+$/) print "node\t" LD "\t" cmd "\t" name
      else print "remote\t" name " " cmd " names a version, URL or repository that is fetched from a registry"
    }
    { buf = buf $0 "\n" }
    END {
      D = jstr(buf, "cwd"); D = D ~ /^\// ? norm(D) : "?"
      parse(jstr(buf, "command"))
    }')
  while IFS='	' read -r _ge_kind _ge_a _ge_b _ge_c; do
    case $_ge_kind in
      remote) printf '%s' "$_ge_a"; return 0 ;;
      node|py)
        if [ "$_ge_a" = '?' ]; then
          printf '%s %s runs in a directory Forge cannot follow, so it cannot check that %s is installed there' "$_ge_c" "$_ge_b" "$_ge_b"
          return 0
        fi
        guard_installed "$_ge_kind" "$_ge_a" "$_ge_b" && continue
        if [ "$_ge_kind" = node ]; then _ge_w=node_modules/.bin; else _ge_w=.venv/bin; fi
        printf '%s is not installed where the command runs: no %s/%s from %s up to the repository root, so %s would fetch it from a registry and run it' "$_ge_b" "$_ge_w" "$_ge_b" "$_ge_a" "$_ge_c"
        return 0 ;;
    esac
  done <<EOF
$_ge_found
EOF
  return 1
}

# guard_installed <node|py> <dir> <name>: <name> is installed in <dir> or a parent,
# up to the repository root (a directory holding .git).
guard_installed() {
  _gi_d=$2
  while :; do
    if [ "$1" = node ]; then
      { [ -e "$_gi_d/node_modules/.bin/$3" ] || [ -f "$_gi_d/node_modules/$3/package.json" ]; } && return 0
    else
      [ -x "$_gi_d/.venv/bin/$3" ] && return 0
    fi
    { [ -e "$_gi_d/.git" ] || [ "$_gi_d" = / ] || [ -z "$_gi_d" ]; } && return 1
    _gi_d=$(dirname "$_gi_d")
  done
}

# the matching rules in guard.rules order (denies first), "decision<TAB>id<TAB>check<TAB>review<TAB>description",
# up to the first one without a check: nothing after it can win
hits=$(printf '%s' "$input" | awk -F '\t' -v rules="$dir/guard.rules" '
  { buf = buf $0 " " }
  END {
    if (!match(buf, /"command"[[:space:]]*:[[:space:]]*"/)) exit 0
    s = substr(buf, RSTART + RLENGTH); n = length(s); cmd = ""
    for (i = 1; i <= n; i++) {
      c = substr(s, i, 1)
      if (c == "\"") break
      if (c == "\\") { cmd = cmd c substr(s, i + 1, 1); i++; continue }
      cmd = cmd c
    }
    while ((getline line < rules) > 0) {
      if (line ~ /^#/ || line == "") continue
      split(line, f, "\t")
      if ((f[2] != "deny" && f[2] != "ask") || cmd !~ f[3]) continue
      d = f[4]; gsub(/\\/, "\\\\", d); gsub(/"/, "\\\"", d)
      printf "%s\t%s\t%s\t%s\t%s\n", f[2], f[1], (f[5] == "" ? "-" : f[5]), (f[6] == "" ? "-" : f[6]), d
      if (f[5] == "") exit 0
    }
  }
') || exit 1
[ -n "$hits" ] || exit 0
out=''
while IFS='	' read -r decision id check question desc; do
  finding=''
  if [ "$check" != - ]; then
    finding=$(guard_check_"$(printf '%s' "$check" | tr '-' '_')") || continue
    finding=$(printf '%s' "$finding" | tr -d '\n\r\t')
  fi
  detail=$(printf '%s' "$finding" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g')
  out=$(printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"%s","permissionDecisionReason":"forge:%s %s%s"}}' "$decision" "$id" "$desc" "${detail:+ Here: $detail.}")
  break
done <<EOF
$hits
EOF
case $out in
  *'"permissionDecision":"ask"'*)
    if [ -z "${FORGE_REVIEWER:-}" ] && [ "${FORGE_ASK_REVIEW:-auto}" != never ] && [ -f "$dir/review.sh" ]; then
      # the reviewer answers this rule's concern only: its description (JSON-escaped in
      # guard.rules), the check's finding, and its review question
      concern=$(printf '%s' "$desc" | sed -e 's/\\"/"/g' -e 's/\\\\/\\/g')${finding:+ Here: $finding.}
      [ "$question" = - ] && question=''
      reviewed=$(printf '%s' "$input" | sh "$dir/review.sh" pre "$id" "$concern" "$question")
      [ -n "$reviewed" ] && out=$reviewed
    fi ;;
esac
[ -z "$out" ] || printf '%s\n' "$out"
